import mongoose from"mongoose";const categorySchema=new mongoose.Schema({name:{type:String,required:!0},slug:{type:String,required:!0,unique:!0},parentId:{type:mongoose.Schema.Types.ObjectId,ref:"category",default:null},isCampaign:{type:Boolean,default:!1},showInNavbar:{type:Boolean,default:!0},active:{type:Boolean,default:!0},order:{type:Number,default:0}},{timestamps:!0}),Category=mongoose.models.category||mongoose.model("category",categorySchema);export default Category;